WITH kept_keys AS (SELECT session_id FROM web_events INTERSECT ALL SELECT session_id FROM web_events WHERE event_time >= '2024-08-01'), reconciled AS (SELECT s.* FROM web_events s JOIN kept_keys k ON s.session_id = k.session_id) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, COUNT(*) FILTER (WHERE page = '/search') AS search_rows FROM reconciled GROUP BY 1;
